using System.ComponentModel.DataAnnotations;

namespace INKED.Application.SizeCharts;

/// <summary>
/// Data the client sends to add one size row to a quoted item. SizeChartID is generated by SQL Server.
/// SizeCharts links to QuotationItems (NOT OrderItems), following the MP1 schema.
/// </summary>
public class CreateSizeChartDto
{
    /// <summary>Must be an existing QuotationItemID.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "QuotationItemId must be an existing quotation item ID.")]
    public int QuotationItemId { get; set; }

    /// <summary>VARCHAR(10), not blank. Examples: XS, M, 2XL, Free Size.</summary>
    [Required, StringLength(10, MinimumLength = 1)]
    public string Size { get; set; } = string.Empty;

    /// <summary>Must be greater than 0.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "Quantity must be greater than 0.")]
    public int Quantity { get; set; }
}
